CREATE USER IF NOT EXISTS "SA" PASSWORD '' ADMIN;             
CREATE CACHED TABLE "PUBLIC"."WAREHOUSE"(
    "WAREHOUSE_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1 RESTART WITH 6) NOT NULL,
    "ACTIVE" BOOLEAN NOT NULL,
    "ADDRESS" CHARACTER VARYING(150) NOT NULL,
    "WAREHOUSE_CODE" CHARACTER VARYING(10) NOT NULL,
    "DISPLAY_ORDER" INTEGER NOT NULL,
    "NAME" CHARACTER VARYING(50) NOT NULL,
    "OPERATION_FOCUS" CHARACTER VARYING(100) NOT NULL,
    "SERVICE_AREA" CHARACTER VARYING(100) NOT NULL,
    "LATITUDE" FLOAT(53),
    "LONGITUDE" FLOAT(53)
);  
ALTER TABLE "PUBLIC"."WAREHOUSE" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_2F" PRIMARY KEY("WAREHOUSE_ID");         
