CREATE CACHED TABLE "PUBLIC"."FARM_CUSTOMER"(
    "FARM_CUSTOMER_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1 RESTART WITH 33) NOT NULL,
    "ADDRESS" CHARACTER VARYING(180) NOT NULL,
    "ANIMAL_TYPE" CHARACTER VARYING(30) NOT NULL,
    "CREATED_AT" TIMESTAMP(6),
    "DEMO_DATA" BOOLEAN NOT NULL,
    "DISTANCE_KM" FLOAT(53) NOT NULL,
    "FARM_CODE" CHARACTER VARYING(20) NOT NULL,
    "FARM_NAME" CHARACTER VARYING(80) NOT NULL,
    "LATITUDE" FLOAT(53),
    "LIVESTOCK_COUNT" INTEGER NOT NULL,
    "LONGITUDE" FLOAT(53),
    "MONTHLY_FEED_QUANTITY" INTEGER NOT NULL,
    "NOTES" CHARACTER VARYING(200),
    "PHONE" CHARACTER VARYING(30) NOT NULL,
    "POSTAL_CODE" CHARACTER VARYING(10) NOT NULL,
    "PREFERRED_FEED" CHARACTER VARYING(80) NOT NULL,
    "RECURRING_DELIVERY_DAY" INTEGER NOT NULL,
    "REPRESENTATIVE_NAME" CHARACTER VARYING(30) NOT NULL,
    "STATUS" CHARACTER VARYING(20) NOT NULL,
    "WAREHOUSE_ID" BIGINT NOT NULL
);               
ALTER TABLE "PUBLIC"."FARM_CUSTOMER" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_AF" PRIMARY KEY("FARM_CUSTOMER_ID"); 
